import{_ as a,o as e,c as d,a3 as r}from"./chunks/framework.BlfGB29P.js";const _=JSON.parse('{"title":"是否建设设计系统","description":"","frontmatter":{"title":"是否建设设计系统","outline":[2,3],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"frontend/decisions/ui/design-system.md","filePath":"frontend/decisions/ui/design-system.md","lastUpdated":1785589115000}'),i={name:"frontend/decisions/ui/design-system.md"};function l(o,t,h,n,s,c){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="是否建设设计系统" tabindex="-1">是否建设设计系统 <a class="header-anchor" href="#是否建设设计系统" aria-label="Permalink to &quot;是否建设设计系统&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>设计系统是设计原则、令牌、组件、内容规范、治理和反馈机制的共同产品。只有一套组件代码或一份 Figma 文件，不等于设计系统。建设是否值得，取决于重复产品规模、一致性问题和组织是否愿意长期维护，而不是品牌想显得成熟。</p><p>工程实践参见<a href="/frontend/guide/engineering/experience/design-systems">设计系统与视觉一致性</a>。</p><h2 id="_1-决策背景" tabindex="-1">1. 决策背景 <a class="header-anchor" href="#_1-决策背景" aria-label="Permalink to &quot;1. 决策背景&quot;">​</a></h2><p>多个产品重复实现按钮和表单会造成体验漂移、无障碍缺陷和升级浪费；过早建设完整系统则可能在真实需求前定义大量无人使用的组件，平台团队成为交付瓶颈。</p><p>决策问题应是“一致性问题是否跨产品重复，以及集中治理能否产生净收益”，而不是“是否要建组件站”。</p><h2 id="_2-硬约束与评价标准" tabindex="-1">2. 硬约束与评价标准 <a class="header-anchor" href="#_2-硬约束与评价标准" aria-label="Permalink to &quot;2. 硬约束与评价标准&quot;">​</a></h2><h3 id="_2-1-组织硬约束" tabindex="-1">2.1 组织硬约束 <a class="header-anchor" href="#_2-1-组织硬约束" aria-label="Permalink to &quot;2.1 组织硬约束&quot;">​</a></h3><ul><li>设计与工程共同拥有，不能只由某一方单向发布；</li><li>基础组件达到无障碍、安全、浏览器和性能基线；</li><li>版本、弃用、迁移和支持责任有明确人员与时间；</li><li>设计令牌有单一来源并能映射到各技术栈；</li><li>产品允许例外，并有记录和反馈进入系统的路径。</li></ul><p>没有持续负责人和采用预算时，不应承诺建设完整设计系统。</p><h3 id="_2-2-评价维度" tabindex="-1">2.2 评价维度 <a class="header-anchor" href="#_2-2-评价维度" aria-label="Permalink to &quot;2.2 评价维度&quot;">​</a></h3><p>比较产品数量、重复模式、品牌关系、跨端需求、交付浪费、一致性缺陷、平台团队容量、采用成本、治理速度和创新自由。</p><h2 id="_3-候选投入层级" tabindex="-1">3. 候选投入层级 <a class="header-anchor" href="#_3-候选投入层级" aria-label="Permalink to &quot;3. 候选投入层级&quot;">​</a></h2><h3 id="_3-1-团队级规范" tabindex="-1">3.1 团队级规范 <a class="header-anchor" href="#_3-1-团队级规范" aria-label="Permalink to &quot;3.1 团队级规范&quot;">​</a></h3><p>共享令牌、基础样式和少量交互规则，不设独立平台。适合一两个产品和单团队，成本低，但一致性依赖协作。</p><h3 id="_3-2-共享组件与文档" tabindex="-1">3.2 共享组件与文档 <a class="header-anchor" href="#_3-2-共享组件与文档" aria-label="Permalink to &quot;3.2 共享组件与文档&quot;">​</a></h3><p>提供高频组件、示例和版本发布，解决代码复用。适合重复 UI 已明显但治理尚轻的组织；设计决策和内容规范可能仍然分散。</p><h3 id="_3-3-完整设计系统" tabindex="-1">3.3 完整设计系统 <a class="header-anchor" href="#_3-3-完整设计系统" aria-label="Permalink to &quot;3.3 完整设计系统&quot;">​</a></h3><p>包含原则、令牌、设计资产、代码组件、模式、内容、无障碍、治理、度量和支持。适合多产品、多团队和长期品牌体系，需要产品化路线和专职或稳定兼职团队。</p><h3 id="_3-4-多品牌或多平台系统" tabindex="-1">3.4 多品牌或多平台系统 <a class="header-anchor" href="#_3-4-多品牌或多平台系统" aria-label="Permalink to &quot;3.4 多品牌或多平台系统&quot;">​</a></h3><p>核心语义令牌与品牌主题、Web 与原生实现分层。只有真实存在多个品牌或平台时才建设，避免用复杂令牌模型预测假想未来。</p><h2 id="_4-关键维度对比" tabindex="-1">4. 关键维度对比 <a class="header-anchor" href="#_4-关键维度对比" aria-label="Permalink to &quot;4. 关键维度对比&quot;">​</a></h2><p>案例是 8 个企业产品、70 名开发者、12 名设计师，用户在产品间切换；审计发现 14 种按钮、9 种错误提示和 36 个键盘缺陷。每季度约 90 人天用于重复修复基础交互。</p><table tabindex="0"><thead><tr><th>投入层级</th><th>能解决的问题</th><th>当前适配</th></tr></thead><tbody><tr><td>团队规范</td><td>基础色彩和间距</td><td>不足，跨产品执行弱</td></tr><tr><td>共享组件</td><td>重复代码和部分交互</td><td>必要，但不足以统一设计决策</td></tr><tr><td>完整设计系统</td><td>令牌、组件、模式和治理</td><td>符合规模与重复成本</td></tr><tr><td>多品牌系统</td><td>品牌主题分层</td><td>暂不需要，只有一个品牌</td></tr></tbody></table><h2 id="_5-场景化推荐结论" tabindex="-1">5. 场景化推荐结论 <a class="header-anchor" href="#_5-场景化推荐结论" aria-label="Permalink to &quot;5. 场景化推荐结论&quot;">​</a></h2><p>推荐建设单品牌设计系统，但分阶段交付：</p><ol><li>先建立语义色彩、排版、间距、焦点和状态令牌；</li><li>用按钮、输入、选择器、对话框、表格等覆盖 60% 高频页面；</li><li>补充表单、空状态、错误恢复和权限提示等组合模式；</li><li>建立提案、例外、弃用、迁移和支持流程；</li><li>用采用率、重复缺陷和交付时间决定下一批投入。</li></ol><p>不先建设多品牌架构和几十个低频组件。首期选择两个新页面和一个遗留页面试点，验证采用成本。</p><h2 id="_6-引入后的后果" tabindex="-1">6. 引入后的后果 <a class="header-anchor" href="#_6-引入后的后果" aria-label="Permalink to &quot;6. 引入后的后果&quot;">​</a></h2><p>设计系统能集中修复无障碍和一致性问题，让产品团队复用经过验证的决策。代价是平台团队、版本维护、文档、设计资产同步和迁移预算；产品团队也会失去部分局部自由。</p><p>治理不能只靠禁止。系统必须提供清楚的贡献、例外和实验路径，否则团队会绕开平台。例外数据反过来揭示系统缺口。</p><p>退出或缩减时，应保留开放的令牌格式和稳定组件契约。若所有设计数据只能存在于单一工具插件中，迁移成本会异常高。</p><h2 id="_7-不适用场景" tabindex="-1">7. 不适用场景 <a class="header-anchor" href="#_7-不适用场景" aria-label="Permalink to &quot;7. 不适用场景&quot;">​</a></h2><ul><li>单产品、单团队且重复成本很低时，团队规范和局部组件足够。</li><li>没有设计与工程共同负责人时，不应建设只由代码驱动的“系统”。</li><li>不要先做组件展示站再寻找消费者。</li><li>不要追求 100% 统一，特殊产品体验需要可审查例外。</li><li>组件库采购不能替代品牌原则、内容和治理。</li></ul><h2 id="_8-填写完成的决策记录" tabindex="-1">8. 填写完成的决策记录 <a class="header-anchor" href="#_8-填写完成的决策记录" aria-label="Permalink to &quot;8. 填写完成的决策记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>问题</td><td>八个企业产品是否建设统一设计系统</td></tr><tr><td>硬约束</td><td>设计与工程共同负责；无障碍 AA；有迁移预算；单品牌</td></tr><tr><td>候选</td><td>团队规范、共享组件、完整系统、多品牌系统</td></tr><tr><td>决定</td><td>分阶段建设单品牌设计系统</td></tr><tr><td>首期范围</td><td>核心令牌、7 类组件、4 类组合模式、治理流程</td></tr><tr><td>明确不做</td><td>多品牌抽象、全量遗留迁移、低频组件大全</td></tr><tr><td>接受代价</td><td>4 人稳定平台小组；产品迁移和版本支持</td></tr><tr><td>成功指标</td><td>活跃产品采用率、重复组件数、无障碍缺陷、交付人天、例外处理时长</td></tr></tbody></table><h2 id="_9-复查条件" tabindex="-1">9. 复查条件 <a class="header-anchor" href="#_9-复查条件" aria-label="Permalink to &quot;9. 复查条件&quot;">​</a></h2><p>两个季度采用率低于 40%、平台响应时间持续超过产品自行实现时间、重复缺陷没有下降、品牌战略变化，或维护成本超过节省人天时复查。可能的调整包括缩小到令牌和基础组件、开放更多贡献，或停止低价值组件维护。</p>',39)])])}const u=a(i,[["render",l]]);export{_ as __pageData,u as default};
